For the closure $\widehat\beta$ of a braid $\beta$ with crossings $j=1,\dots,c$ of signs $\varepsilon_j$ with $\mu$ components,
\begin{gather*}
   \mathrm{LG}(\widehat\beta;t_0,t_1)\;=\;(-1)^{\mu-1}\;\mathbbm E\Bigl[\det\bigl(1-B(x)'\bigr)\,\det\bigl(1-\widetilde{B}(y)'\bigr)\Bigr],\\
   \mathbbm E[x_j]=t_0^{\varepsilon_j},\qquad \mathbbm E[y_j]=t_1^{\varepsilon_j},\qquad \mathbbm E[x_jy_j]=1,
\end{gather*}
where $M'$ denotes $M$ with its first row and column removed.

The first claim is read off from \eqref{eq.R}--\eqref{eq.R2}. Hence $R_r$ is block diagonal with respect to the
nine homogeneous components of $W\otimes W$, which have bases
\begin{equation}\label{eq.sectors}
\begin{gathered}
(e_{11});\quad (e_{21},e_{12});\quad (e_{31},e_{13});\quad (e_{22});\quad (e_{33});\quad
(e_{41},e_{23},e_{32},e_{14});\\ (e_{42},e_{24});\quad (e_{43},e_{34});\quad (e_{44}),
\end{gathered}
\end{equation}
of bidegrees $(0,0),(1,0),(0,1),(2,0),(0,2),(1,1),(2,1),(1,2),(2,2)$. The determinants of the nine blocks are
$-1$, $-t_0$, $-t_1$, $t_0$, $t_1$, $t_0t_1$, $-t_0$, $-t_1$, $-1$.

\label{def.V}
For a braid word $w$ on $n$ strands,
\[
   V(w;r)\;=\;\sum_{(m_2,\dots,m_n)\in\{1,2,3,4\}^{n-1}} h_{m_2}h_{m_3}\cdots h_{m_n}\;
   \bigl\langle e_{(1,m_2,\dots,m_n)},\ \varrho_r(w)\,e_{(1,m_2,\dots,m_n)}\bigr\rangle\ \in\mathbbm K .
\]

\label{lem.twist}
Let $F_r\in\mathrm{End}(W\otimes W)$ be the diagonal operator $F_r\,e_{ij}=r^{\beta(e_i)\alpha(e_j)}\,e_{ij}$. Then
$R_r=F_rR_1F_r^{-1}$, and $V(w;r)=V(w;1)$ for every braid word $w$ and every $r\in\mathbbm K^\times$.

\label{lem.minors}
Let $M,N\in\mathrm{End}(U)$.
\begin{enumerate}\renewcommand{\roman{enumi}}{\roman{enumi}}
\item ${\textstyle\bigwedge}(MN)={\textstyle\bigwedge}(M){\textstyle\bigwedge}(N)$ and ${\textstyle\bigwedge}(1)=1$.
\item $\langle u_T,{\textstyle\bigwedge}(M)u_S\rangle=\det M[T|S]$ if $|T|=|S|$, and $0$ otherwise, where the determinant of the empty
      matrix is $1$.
\end{enumerate}

\label{thm.A}
All matrix entries of $G(x,y)$ and $G^{-}(x,y)$ have degree $\le1$ in each of $x$ and $y$, and
\begin{enumerate}\renewcommand{\roman{enumi}}{\roman{enumi}}
\item $\mathsf R=\mathbbm E_{t_0,t_1}\bigl[G(x,y)\bigr]$;
\item $\mathsf R^{-1}=\mathbbm E_{t_0^{-1},t_1^{-1}}\bigl[G^{-}(x,y)\bigr]$.
\end{enumerate}

\label{thm.B}
Let $w$ be a braid word on $n$ strands with $c$ crossings, and let $L$ be its closure, a link with $\mu$ components.
Then
\begin{equation}\label{eq.main}
   V_1(L;t_0,t_1)=(-1)^{\mu-1}\;\mathbbm E\bigl[P_w(x)\,\widetilde{P}_w(y)\bigr]
     =(-1)^{\mu-1}\;\mathbbm E\Bigl[\det\bigl(1-B(x)'\bigr)\,\det\bigl(1-\widetilde{B}(y)'\bigr)\Bigr].
\end{equation}
Equivalently, by \eqref{eq.VV1}, the state sum of Definition~\ref{def.V} is
$V(w)=(-1)^{n-1+c}\,\mathbbm E\bigl[P_w(x)\,\widetilde{P}_w(y)\bigr]$.

\label{def.T}
The \emph{edge matrices} $T^a(x)$ and $T^b(y)$ have rows and columns indexed by the edges, and
\begin{align*}
   T^a(x)&=\sum_{j=1}^c\Bigl(E_{o'_jo_j}+(1-x_j)\,E_{u'_jo_j}+x_j\,E_{u'_ju_j}\Bigr),\\
   T^b(y)&=\sum_{j=1}^c\Bigl(y_j\,E_{o'_jo_j}+(1-y_j)\,E_{u'_jo_j}+E_{u'_ju_j}\Bigr),
\end{align*}
where $E_{e'e}$ is the matrix unit with entry $1$ in row $e'$ and column $e$.

\label{prop.braidp}
Let $w$ be a braid word in which every position is moved by at least one letter, let $L$ be its closure and $D_w$
its closure diagram. Then $V_1(L;t_0,t_1)=\Upsilon(D_w,\hat e)$ for every edge $\hat e$ of $D_w$.

\label{cor.treesD}
Let $D$ be a connected diagram of $L$ with at least one crossing and let $\hat e$ be an edge of $D$. Then the
statements of Proposition~\ref{prop.trees} hold for $D$ and $\hat e$: with the $a$-trees and the $b$-trees of
Definition~\ref{def.trees} for the diagram $D$,
\begin{gather*}
   P_{D,\hat e}(x)=\sum_{\varphi}\ \prod_{j=1}^cp_{\vartheta_j(\varphi)}(x_j),\qquad
   \widetilde{P}_{D,\hat e}(y)=\sum_{\psi}\ \prod_{j=1}^cp_{\vartheta_j(\psi)}(y_j),\\
   V_1(L;t_0,t_1)=(-1)^{\mu-1}\sum_{(\varphi,\psi)}\ \prod_{j=1}^cW_j\bigl(\vartheta_j(\varphi),\vartheta_j(\psi)\bigr).
\end{gather*}
